        var eAtu = (typeof BasesCat !== "undefined") ? BasesCat.get(fonteAtu === "GOINFRA" ? "AGETOP" : fonteAtu) : null;
        if (!eAtu || !eAtu.chaveStatus) { pinta("Este banco não tem atualização online."); return; }
