      // recolher/expandir a etapa (accordion) — só marcação, nada de persistir
      if (t.dataset.toggleEtapa) { this.toggleEtapa(t.dataset.toggleEtapa); return; }
      // reordenar etapa "etapaId|dir" (dir -1 sobe / 1 desce)
