            try { var cxJ = document.querySelector("#aba-conteudo .cx[data-cx-sub]"); if (cxJ) subJ = cxJ.getAttribute("data-cx-sub") || subJ; } catch (eSj) {}
            Janelas.abrir(this.orcAtual.id, this.aba || "planilha", subJ);
