        if (m2 && !m2.erro && m2.cabe) {
          portas.push({ id: "sem-origem-ia", bytes: m2.bytes, libera: rec.bytes - m2.bytes, aplica: ["marca-ia", "sem-origem-ia"], ia: { texto: 1, origem: 1 } });
        }
